mapper.select:
select m.material_id, m.material_code, m.material_name, m.material_type, m.specification, m.origin_place, m.batch_no, m.supplier_id, m.supplier_name, m.unit, m.quality_grade, m.owner_user_id, m.owner_user_name, count(r.identity_id) as rfid_count, sum(case when r.bind_goods_id is not null then 1 else 0 end) as used_rfid_count, sum(case when r.identity_id is not null and r.bind_goods_id is null then 1 else 0 end) as unused_rfid_count, m.del_flag, m.create_by, m.create_time, m.update_by, m.update_time, m.remark from aggregate_material m left join aggregate_rfid_identity r on r.material_id = m.material_id and r.del_flag = '0'
and m.del_flag = '0' and m.material_code like concat('%', #{materialCode}, '%') and m.material_name like concat('%', #{materialName}, '%') and m.material_type = #{materialType} and m.batch_no = #{batchNo} and m.owner_user_id = #{ownerUserId}
group by m.material_id, m.material_code, m.material_name, m.material_type, m.specification, m.origin_place, m.batch_no, m.supplier_id, m.supplier_name, m.unit, m.quality_grade, m.owner_user_id, m.owner_user_name, m.del_flag, m.create_by, m.create_time, m.update_by, m.update_time, m.remark order by m.material_id desc
